add_action( 'woocommerce_after_single_product_summary', 'perfectpixel_related_categories_grid', 25 );

function perfectpixel_related_categories_grid() {
	global $product;
	if ( ! $product ) {
		return;
	}
	$ids = array_diff( $product->get_category_ids(), array( (int) get_option( 'default_product_cat' ) ) );
	if ( ! $ids ) {
		return;
	}
	echo '<section class="related-categories"><h2>' . esc_html( '{{related_categories_title}}' ) . '</h2>';
	echo do_shortcode( sprintf( '[product_categories ids="%s" columns="%d" hide_empty="1"]', implode( ',', array_map( 'absint', $ids ) ), max( 1, (int) '{{related_categories_columns}}' ) ) );
	echo '</section>';
}
